function edgeColor(e){ return e>=0 ? T.green : T.red; }
function catColor(v){
  if(v>=54)return"#10B981"; if(v>=51.5)return"#6EE7B7"; if(v>=50.4)return"#D1FAE5";
  if(v>49.6)return"#F3F4F6"; if(v>48.5)return"#FEE2E2"; if(v>46)return"#FCA5A5"; return"#EF4444"; }
function catText(v){ return (v>=54||v<=46)?"#fff":"#374151"; }
function pctC(v){ if(v>=65)return"#10B981"; if(v>=55)return"#6EE7B7"; if(v>=48)return"#D1FAE5"; if(v>=40)return"#FEE2E2"; if(v>=28)return"#FCA5A5"; return"#EF4444"; }
